import sys

def main():
    input_data = sys.stdin.read().splitlines()
    if not input_data:
        return

    first_line = input_data[0].split()
    T = int(first_line[0])
    M = first_line[1]

    english_alphabet = "abcdefghijklmnopqrstuvwxyz"
    mapping = {}

    for i in range(26):
        byteland_char = english_alphabet[i]
        english_char = M[i]
        mapping[byteland_char] = english_char
        mapping[byteland_char.upper()] = english_char.upper()

    sentences = input_data[1:T+1]
    results = []

    for sentence in sentences:
        translated_chars = []
        for char in sentence:
            if char == '_':
                translated_chars.append(' ')
            elif char in mapping:
                translated_chars.append(mapping[char])
            else:
                translated_chars.append(char)
        results.append("".join(translated_chars))

    for res in results:
        print(res)

if __name__ == "__main__":
    main()
